      const dateQuery = buildDateQuery(dateKey);
      console.log("[TEAMLY DEBUG][loadMain #"+reqId+"] START token="+(_authToken?_authToken.slice(0,20)+"...":"NULL")+" orgId="+orgId+" dateFilter="+dateKey);
